use crate::api::client::ApiClient;
use crate::error::ArgumentError;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{DateTime, Datelike, NaiveDate, Utc};
use serde::Serialize;
use std::collections::BTreeMap;

pub struct BillWeeklyCommand;

#[derive(Serialize)]
struct WeeklyBill {
    week: String,
    billable_seconds: i64,
}

#[derive(Serialize)]
struct WeeklyBillReport {
    weeks: Vec<WeeklyBill>,
    total_billable_seconds: i64,
}

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let since_boundary = parse_boundary(since.as_deref())?;
        let until_boundary = parse_boundary(until.as_deref())?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let weekly_seconds = aggregate(&entries, since_boundary, until_boundary);
        let output = if json {
            format_json(&weekly_seconds)
        } else {
            format_human(&weekly_seconds)
        };
        print!("{output}");
        Ok(())
    }
}

fn parse_boundary(value: Option<&str>) -> ResultWithDefaultError<Option<DateTime<Utc>>> {
    value
        .map(|value| {
            DateTime::parse_from_rfc3339(value)
                .map(|date| date.with_timezone(&Utc))
                .map_err(|_| Box::new(ArgumentError::InvalidDateTime(value.to_string())) as _)
        })
        .transpose()
}

fn aggregate(
    entries: &[TimeEntry],
    since: Option<DateTime<Utc>>,
    until: Option<DateTime<Utc>>,
) -> BTreeMap<NaiveDate, i64> {
    let mut weekly_seconds = BTreeMap::<NaiveDate, i64>::new();

    for entry in entries {
        if !entry.billable
            || entry.is_running()
            || since.is_some_and(|boundary| entry.start < boundary)
            || until.is_some_and(|boundary| entry.start >= boundary)
        {
            continue;
        }

        let days_since_monday = entry.start.weekday().num_days_from_monday() as i64;
        let monday = entry.start.date_naive() - chrono::Duration::days(days_since_monday);
        *weekly_seconds.entry(monday).or_default() += entry.duration;
    }

    weekly_seconds
}

fn format_human(weekly_seconds: &BTreeMap<NaiveDate, i64>) -> String {
    if weekly_seconds.is_empty() {
        return "(no data)\n".to_string();
    }

    let total = weekly_seconds.values().sum::<i64>();
    let mut output = weekly_seconds
        .into_iter()
        .map(|(monday, seconds)| format!("{}  {seconds}s", monday.format("%Y-%m-%d")))
        .collect::<Vec<_>>()
        .join("\n");
    output.push_str(&format!("\nTotal  {total}s\n"));
    output
}

fn format_json(weekly_seconds: &BTreeMap<NaiveDate, i64>) -> String {
    let weeks = weekly_seconds
        .iter()
        .map(|(monday, seconds)| WeeklyBill {
            week: monday.format("%Y-%m-%d").to_string(),
            billable_seconds: *seconds,
        })
        .collect::<Vec<_>>();
    let report = WeeklyBillReport {
        total_billable_seconds: weeks.iter().map(|week| week.billable_seconds).sum(),
        weeks,
    };
    format!(
        "{}\n",
        serde_json::to_string(&report).expect("failed to serialize weekly bill")
    )
}

